using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_post"), Description("Fetches a post by ID from an external API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        ILogger<ApiFetchTool> logger,
        [Description("The numeric ID of the post to fetch (1-100).")] int postId)
    {
        logger.LogInformation("Fetching post {PostId}", postId);

        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"posts/{postId}");

        if (!response.IsSuccessStatusCode)
        {
            var body = await response.Content.ReadAsStringAsync();
            logger.LogWarning("API returned {Status}: {Body}", (int)response.StatusCode, body);
            return $"Error: API returned {(int)response.StatusCode}";
        }

        var post = await response.Content.ReadFromJsonAsync<JsonElement>();
        return post.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a summarization prompt for the given text.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Optional desired length: 'short', 'medium', or 'long'. Defaults to 'medium'.")] string? length = "medium")
    {
        return
        [
            new McpServerPromptMessage(
                McpServerPromptMessageRole.User,
                new McpServerPromptContentPart
                {
                    Text = $"Summarize the following text in a {length} summary. " +
                           "Preserve key facts and conclusions.\n\n" +
                           $"---\n{text}\n---"
                })
        ];
    }
}

